"""
스모크 테스트 (Playwright, Chromium). 실행: python3 tests/smoke.py
- 방치형 행동은 Playwright 가상 시계(page.clock)로 시간을 앞당겨 검증한다.
- 환경변수 STUB_ICONS=1 : 아이콘 폰트를 못 받는 환경에서 아이콘을 원형 마크로 대체(레이아웃 측정용)
- 환경변수 SHOT_DIR=경로 : 스크린샷 저장 위치 (기본 tests/out)
환경변수 USER_CODE / DEV_CODE : 초대코드·개발자 코드 원문 (가입·개발자 코드 테스트용. 없으면 해당 테스트가 실패한다)
실패한 항목 이름이 FAILED 목록으로 출력된다. 종료 코드는 실패가 있으면 1.
"""
import json, os, sys
from pathlib import Path
from playwright.sync_api import sync_playwright

ROOT = Path(__file__).resolve().parent.parent
URL = (ROOT / 'index.html').as_uri()
SHOTS = Path(os.environ.get('SHOT_DIR', ROOT / 'tests' / 'out'))
SHOTS.mkdir(parents=True, exist_ok=True)
STUB = ".material-symbols-rounded{color:transparent!important;background:radial-gradient(circle,var(--accent) 34%,transparent 38%)!important}"

UCODE = os.environ.get('USER_CODE', 'NO-USER-CODE')   # 일반 초대코드 원문 (저장소에는 해시만 있다). 가입 테스트에 필요
DCODE = os.environ.get('DEV_CODE', '')                 # 개발자 코드 원문. 개발자 코드 테스트에 필요
R, FAIL = {}, []
def check(name, cond, info=None):
    R[name] = info if info is not None else bool(cond)
    if not cond:
        FAIL.append(name); print("FAIL", name, str(info)[:300], flush=True)

def rect(pg, sel):
    return pg.evaluate("s=>{const r=document.querySelector(s).getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height,r:r.right,b:r.bottom}}", sel)
def text(pg, sel):
    return pg.locator(sel).first.inner_text()
def ev(pg, js):
    return pg.evaluate(js)


# 기존 테스트가 쓰는 5x7 직사각형 맵(제1~3구역). 실제 게임 맵(window.__M)은 별도 테스트가 검사한다.
LEGACY_JS = """
;window.__M = DANGER_ZONES.map(z => z.map.slice());
({'제1구역': ['SaadEcc', 'a#d#c#c', 'aadeecc', 'b#b#e#C', 'bbEeedd'], '제2구역': ['SaabbdE', 'a#a#b#d', 'aacbbdd', 'c#c#e#e', 'CcceeEe'], '제3구역': ['SaabbeE', 'a#a#b#e', 'aaccbee', 'd#c#d#e', 'dEccddC']});
DANGER_ZONES.forEach(z => { const L = {'제1구역': ['SaadEcc', 'a#d#c#c', 'aadeecc', 'b#b#e#C', 'bbEeedd'], '제2구역': ['SaabbdE', 'a#a#b#d', 'aacbbdd', 'c#c#e#e', 'CcceeEe'], '제3구역': ['SaabbeE', 'a#a#b#e', 'aaccbee', 'd#c#d#e', 'dEccddC']}[z.id]; if (L) z.map = L; });
"""

with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={'width': 1440, 'height': 900})
    pg = ctx.new_page()
    errs = []
    pg.on('pageerror', lambda e: (errs.append('PAGEERROR ' + str(e)), print('PAGEERROR', e)))
    pg.route('**/*fonts.g*', lambda r: r.abort())
    def _data_js(route):  # data.js 뒤에 옛 맵 덮어쓰기를 붙여서 내려 준다 (게임 코드는 그대로)
        body = (ROOT / 'js' / 'data.js').read_text(encoding='utf8') + LEGACY_JS
        if os.environ.get('TEST_PATCH_HASH'):  # 실제 코드를 모를 때: 시험용 코드의 해시로 바꿔서 돌린다 (저장소 파일은 그대로)
            import hashlib, re
        route.fulfill(body=body, content_type='application/javascript; charset=utf-8')
    pg.route('**/js/data.js', _data_js)
    def _auth_js(route):
        body = (ROOT / 'js' / 'auth.js').read_text(encoding='utf8')
        if os.environ.get('TEST_PATCH_HASH'):
            import hashlib, re
            body = re.sub(r"\{ hash: '[0-9a-f]{64}', max: 50 \}", "{ hash: '" + hashlib.sha256(UCODE.encode()).hexdigest() + "', max: 50 }", body)
        route.fulfill(body=body, content_type='application/javascript; charset=utf-8')
    ctx.route('**/js/auth.js', _auth_js)
    def _cloud_js(route): # 테스트는 서버 없이 돌린다 (실제 주소·키가 들어 있어도 비워서 서버 연결·가입 페이지 이동을 끈다)
        import re
        route.fulfill(body=re.sub(r"const CLOUD = \{[^}]*\};", "const CLOUD = { url: '', key: '' };", (ROOT / 'js' / 'cloud.js').read_text(encoding='utf8')), content_type='application/javascript; charset=utf-8')
    ctx.route('**/js/cloud.js', _cloud_js)
    pg.clock.install()

    def load(clear=False):
        pg.goto(URL)
        if clear:
            pg.evaluate("localStorage.clear()"); pg.reload()
        if os.environ.get('STUB_ICONS'):
            pg.add_style_tag(content=STUB)
        pg.wait_for_timeout(250)
    load(clear=True)
    def ff(sec):
        pg.clock.fast_forward(int(sec * 1000)); pg.wait_for_timeout(120)

    def sw(sel_id, on):  # 스위치(숨긴 체크박스)는 라벨을 눌러 바꾼다
        if pg.locator('#' + sel_id).is_checked() != on:
            pg.locator(f'label.switch:has(#{sel_id})').click()
    def go(node):  # 지도 노드 이동: 즉시 이동이라 확인창이 없다
        pg.click(f'[data-node="{node}"]'); pg.wait_for_timeout(100)
    def go_zone(zid):  # 지상 구역: 이동장치에서 구역을 고르고 1분 동안 내려간다
        if ev(pg, "state.location") != '이동장치': go('이동장치')
        pg.click(f'#choices button:has-text("{zid}")'); pg.wait_for_timeout(100); run_confirm(); ff(65)
    def run_confirm():
        pg.click('[data-act="action-run"]'); pg.wait_for_timeout(100)
    def make_char(name='테스트', skip_tour=True, weapon='훈련용 검'):  # 튜토리얼 빠르게 통과 (새 저장 필요)
        pg.click('#tutSkipStory'); pg.wait_for_timeout(60)
        pg.fill('#ctName', name); pg.click('#ctNext'); pg.fill('#ctAbility', '그림자 이동')
        for k, n in [('str', 3), ('agi', 3), ('int', 2), ('wil', 2), ('sen', 1), ('luk', 1)]:
            for _ in range(n): pg.click(f'[data-ct="{k}"][data-d="1"]')
        pg.click('#ctDone'); pg.wait_for_timeout(150)
        if skip_tour:
            pg.click('#tutSkip'); pg.wait_for_timeout(60)
            pg.click(f'[data-weapon="{weapon}"]'); pg.click('#tutWeaponOk'); pg.wait_for_timeout(100)

    # ================= 튜토리얼: 안드로이드 리코 → 캐릭터 생성 → 화면 안내 → 무기 선택 =================
    check('tutorial_story_first_run', pg.locator('#tutStory').is_visible() and not ev(pg, "state.tutorialDone") and not ev(pg, "state.created") and '클론' in ev(pg, "TUTORIAL_STORY.map(p=>p.text).join('')"))
    check('tutorial_story_pages', ev(pg, "TUTORIAL_STORY.length")== 7 and pg.locator('#tutDots i').count() == 7 and text(pg, '#tutNextStory') == '다음' and pg.locator('#tutNpc').is_hidden())
    pg.screenshot(path=str(SHOTS / 'tutorial_story.png'))
    for _ in range(4): pg.click('#tutNextStory'); pg.wait_for_timeout(30)
    check('tutorial_npc_android_congrats', pg.locator('#tutNpc').is_visible() and '리코' in text(pg, '#tutNpc') and '안드로이드' in text(pg, '#tutNpc') and '탄생을 축하' in text(pg, '#tutText'))
    pg.click('#tutNextStory'); pg.wait_for_timeout(30)
    check('tutorial_terminal_handed_over', pg.locator('#tutGift').is_visible() and '단말기' in text(pg, '#tutText'))
    pg.screenshot(path=str(SHOTS / 'tutorial_npc.png'))
    pg.click('#tutNextStory'); pg.wait_for_timeout(30)
    check('tutorial_last_story_button', text(pg, '#tutNextStory') == '캐릭터 만들기')
    pg.click('#tutNextStory'); pg.wait_for_timeout(120)
    check('tutorial_create_step1', pg.locator('#tutCreate').is_visible() and pg.locator('#ctName').count() == 1 and pg.locator('#ctAge').count() == 1 and pg.locator('#ctKeywords').count() == 1 and '1 / 2' in text(pg, '#tutCreateHead'))
    pg.click('#ctNext'); pg.wait_for_timeout(60)
    check('create_requires_name', pg.locator('#ctName').count() == 1 and '이름을 입력' in text(pg, '#toast'))
    pg.fill('#ctName', '<b>하루</b>')
    for bad in ('9', '61', '-3'):
        pg.fill('#ctAge', bad); pg.click('#ctNext'); pg.wait_for_timeout(60)
        check(f'create_age_range_10_60_rejects_{bad}', pg.locator('#ctName').count() == 1 and '10~60' in text(pg, '#toast'))
    check('create_age_input_limits', pg.get_attribute('#ctAge', 'min') == '10' and pg.get_attribute('#ctAge', 'max') == '60' and '필수' in text(pg, '.form-row >> nth=0') and '선택' in text(pg, '.form-row >> nth=1'))
    pg.fill('#ctAge', ''); pg.fill('#ctKeywords', '과묵, 정찰'); pg.click('#ctNext'); pg.wait_for_timeout(100)
    check('tutorial_create_step2', pg.locator('#ctAbility').count() == 1 and pg.locator('#ctAbilityDesc').count() == 1 and pg.locator('.ct-stat').count() == 6 and text(pg, '#ctPool') == '12' and '2 / 2' in text(pg, '#tutCreateHead'))
    check('create_stats_start_equal', ev(pg, "STAT_DEFS.every(d=>cf.stats[d.key]===STAT_BASE)") and ev(pg, "STAT_BASE*6+STAT_POOL")== 12 and ev(pg, "STAT_BASE")== 0 and all(text(pg, f'#ctv-{k}') == '0' for k in ['str', 'agi', 'int', 'wil', 'sen', 'luk']))
    pg.click('#ctRandom'); pg.wait_for_timeout(40)
    check('create_random_stats_uses_all_12', text(pg, '#ctPool') == '0' and ev(pg, "STAT_DEFS.reduce((a,d)=>a+cf.stats[d.key],0)")== 12 and ev(pg, "STAT_DEFS.every(d=>cf.stats[d.key]>=0&&cf.stats[d.key]<=STAT_CAP)"))
    pg.click('#ctReset'); pg.wait_for_timeout(40)
    check('create_stat_reset_button', text(pg, '#ctPool') == '12' and ev(pg, "STAT_DEFS.every(d=>cf.stats[d.key]===0)"))
    check('create_only_name_and_ability_required', '필수' in text(pg, '#tutCreateBody') and ev(pg, "document.querySelectorAll('#tutCreateBody .req').length")== 1 and ev(pg, "document.querySelectorAll('#tutCreateBody .opt').length")== 1)
    pg.click('#ctDone'); pg.wait_for_timeout(60)
    check('create_requires_ability_name', pg.locator('#ctAbility').count() == 1 and not ev(pg, "state.created") and '이능력 이름' in text(pg, '#toast'))
    pg.fill('#ctAbility', '그림자 이동'); pg.fill('#ctAbilityDesc', '그림자 사이를 건너뛰는 능력.\n롤플용 설정.')
    pg.click('#ctDone'); pg.wait_for_timeout(60)
    check('create_requires_all_points', not ev(pg, "state.created") and '분배' in text(pg, '#toast') and pg.locator('#ctAbility').count() == 1)
    pg.click('[data-ct="str"][data-d="-1"]'); check('stat_not_below_zero', text(pg, '#ctv-str') == '0' and text(pg, '#ctPool') == '12')
    for _ in range(14): pg.click('[data-ct="str"][data-d="1"]')
    check('stat_all_12_in_one_stat_allowed', text(pg, '#ctv-str') == '12' and text(pg, '#ctPool') == '0')
    check('stat_effect_preview', '공격력 증가 +7.2%' in text(pg, '#cte-str'), text(pg, '#cte-str'))
    pg.click('[data-ct="str"][data-d="-1"]', click_count=9); pg.wait_for_timeout(40)
    for k, n in [('agi', 3), ('int', 2), ('wil', 2), ('sen', 1), ('luk', 1)]:
        for _ in range(n): pg.click(f'[data-ct="{k}"][data-d="1"]')
    check('pool_zero_after_distribution', text(pg, '#ctPool') == '0' and text(pg, '#ctv-str') == '3')
    pg.screenshot(path=str(SHOTS / 'tutorial_create.png'))
    pg.click('#ctDone'); pg.wait_for_timeout(250)
    c = ev(pg, "JSON.stringify(state.character)"); import json as _j; c = _j.loads(c)
    check('created_character_fixed_start', c['rank'] == 'F' and c['level'] == 1 and ev(pg, "state.money")== 100 and ev(pg, "state.vitals.hp")== 100 and ev(pg, "state.vitals.sp")== 100 and ev(pg, "state.vitals.exp")== 0 and ev(pg, "statsTotal(state.stats)")== 12 and ev(pg, "state.statPoints")== 0, c)
    check('created_character_name_sanitized', c['name'] == 'b하루/b', c['name'])
    check('created_character_saved_text', c['age'] == 20 and c['keywords'] == '과묵, 정찰' and c['ability'] == '그림자 이동' and '롤플용' in c['abilityDesc'])
    check('name_html_stripped', '<' not in c['name'] and '>' not in c['name'])
    check('profile_shows_created', text(pg, '#charName') == c['name'] and 'F등급' in text(pg, '#charMeta') and 'LV.1' in text(pg, '#charMeta') and text(pg, '#money') == '100')
    check('ability_in_profile_tooltip', ev(pg, "document.querySelector('#charName').dataset.tipTitle").endswith('그림자 이동'))
    check('tutorial_tour_started', pg.locator('#tutSpot').is_visible() and pg.locator('#tutCard').is_visible() and not pg.locator('#tutCreate').is_visible() and '리코' in text(pg, '#tutStep'))
    n_steps = ev(pg, "TUTORIAL_STEPS.length"); bad = []
    for i in range(n_steps):
        sp_, cd = rect(pg, '#tutSpot'), rect(pg, '#tutCard')
        tgt = rect(pg, ev(pg, f"TUTORIAL_STEPS[{i}].sel"))
        good = abs(sp_['x'] + 5 - tgt['x']) < 3 and abs(sp_['w'] - tgt['w'] - 10) < 3 and cd['x'] >= 0 and cd['r'] <= 1440 and cd['y'] >= 0 and cd['b'] <= 900 and bool(text(pg, '#tutTitle')) and f'{i + 1} / {n_steps}' in text(pg, '#tutStep')
        if not good: bad.append([i, sp_, tgt, cd])
        if i in (0, 3, 7): pg.screenshot(path=str(SHOTS / f'tutorial_step{i}.png'))
        if i < n_steps - 1: pg.click('#tutNext'); pg.wait_for_timeout(350)
    check('tutorial_each_step_spotlights_target', not bad, bad)
    pg.click('#tutPrev'); pg.wait_for_timeout(300)
    check('tutorial_prev_works', f'{n_steps - 1} / {n_steps}' in text(pg, '#tutStep'))
    pg.click('#tutNext'); pg.wait_for_timeout(300)
    check('tutorial_last_step_goes_to_weapon', text(pg, '#tutNext') == '무기 고르기')
    pg.click('#tutNext'); pg.wait_for_timeout(150)
    check('weapon_pick_six_types', pg.locator('#tutWeapon').is_visible() and ev(pg, "[...document.querySelectorAll('.weapon b')].map(b=>b.textContent).join()")== '검,단검,창,활,너클,총' and pg.locator('#tutWeaponOk').is_disabled())
    check('weapon_not_done_before_pick', not ev(pg, "state.tutorialDone") and ev(pg, "state.equipment['무기']")is None and ev(pg, "state.inventory['소모품'].length")== 0)
    pg.screenshot(path=str(SHOTS / 'tutorial_weapon.png'))
    pg.click('[data-weapon="훈련용 권총"]'); check('weapon_select_enables_ok', not pg.locator('#tutWeaponOk').is_disabled() and pg.locator('.weapon.on').count() == 1)
    pg.click('[data-weapon="훈련용 활"]'); pg.click('#tutWeaponOk'); pg.wait_for_timeout(150)
    check('weapon_equipped_and_kit_given', ev(pg, "state.equipment['무기']")== '훈련용 활' and ev(pg, "state.tutorialDone")== True and ev(pg, "countItem('건조 식량')")== 3 and ev(pg, "countItem('응급 키트')")== 1 and ev(pg, "usedSlots()")== 2 and not pg.locator('#tutorial').is_visible())
    check('all_weapons_equal_power', ev(pg, "WEAPON_NAMES.every(n=>ITEMS[n].atk===3&&ITEMS[n].slot==='무기')") and ev(pg, "WEAPON_NAMES.map(n=>ITEMS[n].weapon).join()")== '검,단검,창,활,너클,총')
    pg.reload(); pg.wait_for_timeout(250)
    if os.environ.get('STUB_ICONS'): pg.add_style_tag(content=STUB)
    check('tutorial_not_shown_again', not pg.locator('#tutorial').is_visible() and ev(pg, "state.created"))
    check('start_vitals_100', ev(pg, "state.vitals.hp")== 100 and ev(pg, "state.vitals.sp")== 100)
    check('default_bgm_volume_25', ev(pg, "state.settings.bgmVolume")== 25)

    # ---- 이제부터는 예전 테스트 기준 상태(12레벨)로 맞춰 나머지 기능을 확인한다 ----
    ev(pg, """(()=>{Object.assign(state.character,{level:12,rank:'B',age:24,keywords:'',title:'선봉 탐색자',name:'이름 없는 탐색자'});
      state.stats={str:18,agi:24,int:21,wil:17,sen:26,luk:9};state.statPoints=1;state.money=1250;state.vitals.exp=180;
      state.equipment={'머리':null,'상의':'경량 방탄복','하의':null,'장갑':null,'신발':'자력 부츠','얼굴':null,'귀':null,'목':null,'손 1':null,'손 2':null,'무기':'플라즈마 블레이드','가방':null};
      state.inventory={'장비':[{n:'정찰용 바이저',q:1},{n:'전술 장갑',q:1},{n:'확장형 전술 가방',q:1}],'소모품':[{n:'응급 키트',q:3},{n:'건조 식량',q:2},{n:'수분 팩',q:2}],'재료':[{n:'합금 파편',q:3},{n:'광물 코어',q:1},{n:'생체 섬유',q:3}]};
      state.logs=[];renderProfile();renderBars();renderBuffs(true);renderBag();renderLogs()})()""")

    # ---------- 기본 / 지도 ----------
    check('title', pg.title() == '공중도시 DEEP LAYER')
    check('default_theme_light', ev(pg, "document.body.dataset.theme") == 'light')
    check('start_location_hq', text(pg, '#mapLocation') == '본부')
    check('map_4_nodes_gate_merged', pg.locator('.map-node').count() == 4 and pg.locator('.map-node.danger').count() == 0)
    check('map_3_links', pg.locator('.node-line').count() == 3)
    check('map_desc_below_name', rect(pg, '#mapDescription')['y'] >= rect(pg, '#mapLocation')['b'] - 1)
    check('map_header_meta_right', rect(pg, '#mapMeta')['r'] > rect(pg, '#mapHead')['r'] - 40 and '공중' in text(pg, '#mapMeta'), text(pg, '#mapMeta'))
    check('no_tactical_map_title', 'TACTICAL' not in text(pg, '.map-panel'))
    check('map_help_in_tools', pg.locator('.map-tools #mapHelp').count() == 1 and pg.locator('.map-hint').count() == 0)
    lg, sg = rect(pg, '.map-log'), rect(pg, '#mapStage')
    check('log_right_of_map_on_desktop', lg['x'] >= sg['r'] - 1 and abs(lg['y'] - sg['y']) < 2 and abs(lg['h'] - sg['h']) < 2 and lg['w'] >= 160 and pg.locator('.log-panel').count() == 0, [lg, sg])
    br, wm = rect(pg, '.brand'), rect(pg, '.world-meta')
    check('header_meta_right_of_logo', wm['x'] >= br['r'] - 1 and abs((wm['y'] + wm['h'] / 2) - (br['y'] + br['h'] / 2)) < 30 and text(pg, '.brand small') == '공중도시')
    ml = rect(pg, '.map-log-label'); mc = rect(pg, '#clearLog'); mls = rect(pg, '#logList'); mlp = rect(pg, '.map-log')
    check('log_label_not_overlapping', ml['b'] <= mls['y'] + 1 and mc['x'] >= ml['r'] and abs((mc['y'] + mc['h'] / 2) - (ml['y'] + ml['h'] / 2)) < 8 and ml['y'] - mlp['y'] >= 3, [ml, mc, mls, mlp])
    check('map_header_top_padding', ev(pg, "getComputedStyle(document.querySelector('#mapHead')).paddingTop")== '18px')
